+    id,
+    from: opts.me,
+    cc: [] as Person[],
+    bcc: [] as Person[],
+    date: opts.now,
+    read: true,
+    starred: false,
+    important: false,
+    labels: ["draft"],
+    category: "primary" as const,
+    attachments: [] as Message["attachments"],
+    snoozedUntil: null,
+    sendAt: null,
+  };
+  if (opts.mode === "new" || opts.source.length === 0) {
