+    ...base,
+    threadId: latest.threadId,
+    to: people.to,
+    cc: people.cc,
+    subject: `Re: ${subjectBase}`,
+    body: `\n\n---\nOn ${new Date(latest.date).toUTCString()}, ${latest.from.name} wrote:\n${quote}`,
+    category: latest.category,
+  };
+}

