function att(id: string, name: string, size: number, mime: string, preview: string): Attachment {
  return { id, name, size, mime, preview };
}

function msg(partial: Omit<Message, "cc" | "bcc" | "attachments" | "snoozedUntil" | "sendAt" | "starred" | "important" | "read"> & Partial<Message>): Message {
  return {
    cc: [],
    bcc: [],
    attachments: [],
    snoozedUntil: null,
    sendAt: null,
    starred: false,
    important: false,
    read: true,
    ...partial,
  };
}

