import { HelpCircle, Menu, Search, Settings, SlidersHorizontal, X } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { colorFor, initials } from "../lib/format";
import { filterThreads } from "../lib/mail";
import { useMail } from "../state/mail-context";

export function TopBar() {
  const mail = useMail();
  const { data, ui, patchUi, mobile, openThread, dispatch, threads } = mail;
  const [focus, setFocus] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const accountRef = useRef<HTMLButtonElement>(null);

  const suggestions = useMemo(() => {
    if (!ui.query.trim()) return [];
    return filterThreads(data.messages, {
      mailbox: "all",
      category: "primary",
      query: ui.query,
      labels: data.labels,
    }).slice(0, 6);
  }, [data.labels, data.messages, ui.query]);

  useEffect(() => {
    if (focus) inputRef.current?.focus();
  }, [focus]);

  const showSearch = !mobile || focus || ui.query.length > 0;
  const name = data.settings.displayName || "Jordan Hale";

  return (
    <header className="topbar">
      <div className="brand">
        <button
          type="button"
          className="icon-btn"
          aria-label={mobile ? "Open navigation" : "Collapse navigation"}
          onClick={() => (mobile ? patchUi({ navOpen: !ui.navOpen }) : patchUi({ navCollapsed: !ui.navCollapsed }))}
        >
          <Menu size={20} />
        </button>
        <h1>Grok 4.7</h1>
      </div>
      {showSearch ? (
        <div className={`search ${focus ? "focus" : ""}`}>
          <Search size={20} />
          <input
            id="q"
            ref={inputRef}
            value={ui.query}
            placeholder="Search mail"
            aria-label="Search mail"
            autoComplete="off"
            onChange={(event) => patchUi({ query: event.target.value, cursor: 0, selected: [] })}
            onFocus={() => setFocus(true)}
            onBlur={() => window.setTimeout(() => setFocus(false), 160)}
            onKeyDown={(event) => {
              if (event.key === "Enter") {
                event.preventDefault();
                dispatch({ type: "remember-search", query: ui.query });
                inputRef.current?.blur();
              }
              if (event.key === "Escape") {
                if (ui.query) patchUi({ query: "" });
                inputRef.current?.blur();
              }
            }}
          />
          {ui.query && (
            <button type="button" className="icon-btn tiny" aria-label="Clear search" onClick={() => patchUi({ query: "" })}>
              <X size={16} />
            </button>
          )}
          <SlidersHorizontal size={18} className="search-tune" />
          {focus && (
            <div className="search-pop" role="listbox" aria-label="Search suggestions">
              {ui.query.trim() ? (
                suggestions.length ? (
                  suggestions.map((thread) => (
                    <button
                      key={thread.threadId}
                      type="button"
                      className="search-hit"
                      onMouseDown={(event) => event.preventDefault()}
                      onClick={() => {
                        dispatch({ type: "remember-search", query: ui.query });
                        openThread(thread.threadId);
                        setFocus(false);
                      }}
                    >
                      <strong>{thread.people}</strong>
                      <span>{thread.subject}</span>
                      <em>{thread.snippet}</em>
                    </button>
                  ))
                ) : (
                  <p className="search-empty">No matches in mail</p>
                )
              ) : (
                <>
                  <p className="search-label">Recent</p>
                  {data.recentSearches.map((query) => (
                    <button key={query} type="button" className="search-hit" onMouseDown={(event) => event.preventDefault()} onClick={() => patchUi({ query })}>
                      <span>{query}</span>
                    </button>
                  ))}
                  <p className="search-label">Search by</p>
                  {["is:unread", "is:starred", "has:attachment", "from:lena", "label:work"].map((query) => (
                    <button key={query} type="button" className="search-hit" onMouseDown={(event) => event.preventDefault()} onClick={() => patchUi({ query })}>
                      <span>{query}</span>
                    </button>
                  ))}
                </>
              )}
              {threads.length > 0 && ui.query && <p className="search-label">{threads.length} in the current results</p>}
            </div>
          )}
        </div>
      ) : (
        <button type="button" className="icon-btn search-launch" aria-label="Search mail" onClick={() => setFocus(true)}>
          <Search size={20} />
        </button>
      )}
      <div className="top-actions">
        <button type="button" className="icon-btn" aria-label="Keyboard shortcuts" onClick={() => patchUi({ helpOpen: true })}>
          <HelpCircle size={20} />
        </button>
        <button type="button" className="icon-btn" aria-label="Settings" onClick={() => patchUi({ settingsOpen: true })}>
          <Settings size={20} />
        </button>
        <button
          ref={accountRef}
          type="button"
          className="avatar"
          style={{ background: colorFor(data.settings.displayName) }}
          aria-label="Account"
          aria-expanded={ui.accountOpen}
          onClick={() => patchUi({ accountOpen: !ui.accountOpen })}
        >
          {initials(name)}
        </button>
        {ui.accountOpen && (
          <div className="account-pop" role="menu">
            <div className="account-card">
              <span className="avatar lg" style={{ background: colorFor(name) }}>
                {initials(name)}
              </span>
              <strong>{name}</strong>
              <em>jordan.hale@northwind.dev</em>
            </div>
            <button type="button" onClick={() => patchUi({ settingsOpen: true, accountOpen: false })}>
              Settings
            </button>
            <button
              type="button"
              onClick={() => {
                const order = ["light", "dark", "system"] as const;
                const index = order.indexOf(data.settings.theme);
                dispatch({ type: "settings", patch: { theme: order[(index + 1) % order.length] } });
              }}
            >
              Theme: {data.settings.theme}
            </button>
            <button
              type="button"
              onClick={() => {
                patchUi({ accountOpen: false, composeId: null, activeThreadId: null });
                dispatch({ type: "sign-out" });
              }}
            >
              Sign out
            </button>
          </div>
        )}
      </div>
    </header>
  );
}

args.streamContent:
import {
  Archive,
  ArchiveRestore,
  ChevronLeft,
  ChevronRight,
  Clock3,
  Inbox,
  Mail,
  MailOpen,
  MoreVertical,
  RefreshCw,
  Tag,
  Trash2,
  AlertOctagon,
} from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { snoozePresets } from "../lib/format";
import { useMail } from "../state/mail-context";
import { PopMenu } from "./overlay";

export function Toolbar({ variant }: { variant: "list" | "thread" }) {
  const mail = useMail();
  const checkbox = useRef<HTMLInputElement>(null);
  const [spin, setSpin] = useState(false);
  const [menu, setMenu] = useState<{ id: "more" | "snooze" | "label" | "move"; anchor: HTMLElement } | null>(null);
  const ids = variant === "thread" ? (mail.ui.activeThreadId ? [mail.ui.activeThreadId] : []) : mail.ui.selected;
  const total = mail.threads.length;
  const allSelected = total > 0 && mail.ui.selected.length === total;
  const someSelected = mail.ui.selected.length > 0 && !allSelected;

  useEffect(() => {
    if (checkbox.current) checkbox.current.indeterminate = someSelected;
  }, [someSelected]);

  const showBulk = ids.length > 0;
  const inTrash = mail.ui.mailbox === "trash";
  const inSpam = mail.ui.mailbox === "spam";

  return (
    <div className="toolbar">
      <div className="toolbar-left">
        {variant === "thread" && !mail.split && (
          <button type="button" className="icon-btn" aria-label="Back to list" onClick={mail.closeThread}>
            <ChevronLeft size={20} />
          </button>
        )}
        {variant === "list" && (
          <label className="check">
            <input
              ref={checkbox}
              type="checkbox"
              aria-label="Select"
              checked={allSelected}
              onChange={() => (allSelected ? mail.clearSelection() : mail.selectMany(mail.threads.map((thread) => thread.threadId)))}
            />
          </label>
        )}
        {variant === "list" && !showBulk && (
          <button
            type="button"
            className={`icon-btn ${spin ? "spin" : ""}`}
            aria-label="Refresh"
            onClick={() => {
              setSpin(true);
              mail.dispatch({ type: "tick" }, { silent: true });
              window.setTimeout(() => setSpin(false), 600);
            }}
          >
            <RefreshCw size={18} />
          </button>
        )}
        {showBulk && (
          <>
            {!inTrash && !inSpam && (
              <button type="button" className="icon-btn" aria-label="Archive" onClick={() => mail.archive(ids)}>
                <Archive size={18} />
              </button>
            )}
            {(inTrash || inSpam || mail.ui.mailbox === "all") && (
              <button type="button" className="icon-btn" aria-label="Move to inbox" onClick={() => mail.moveToInbox(ids)}>
                <ArchiveRestore size={18} />
              </button>
            )}
            <button type="button" className="icon-btn" aria-label="Report spam" onClick={() => mail.spam(ids)}>
              <AlertOctagon size={18} />
            </button>
            <button type="button" className="icon-btn" aria-label="Delete" onClick={() => (inTrash ? mail.deleteForever(ids) : mail.trash(ids))}>
              <Trash2 size={18} />
            </button>
            <button
              type="button"
              className="icon-btn"
              aria-label={variant === "thread" ? "Mark as unread" : "Mark as read"}
              onClick={() => mail.mark(ids, variant !== "thread")}
            >
              {variant === "thread" ? <Mail size={18} /> : <MailOpen size={18} />}
            </button>
            <button type="button" className="icon-btn" aria-label="Snooze" onClick={(event) => setMenu({ id: "snooze", anchor: event.currentTarget })}>
              <Clock3 size={18} />
            </button>
            <button type="button" className="icon-btn" aria-label="Move to" onClick={(event) => setMenu({ id: "move", anchor: event.currentTarget })}>
              <Inbox size={18} />
            </button>
            <button type="button" className="icon-btn" aria-label="Label" onClick={(event) => setMenu({ id: "label", anchor: event.currentTarget })}>
              <Tag size={18} />
            </button>
          </>
        )}
        <button type="button" className="icon-btn" aria-label="More" onClick={(event) => setMenu({ id: "more", anchor: event.currentTarget })}>
          <MoreVertical size={18} />
        </button>
        {variant === "list" && mail.ui.mailbox === "trash" && (
          <button type="button" className="text-btn" onClick={mail.emptyTrash}>
            Empty trash now
          </button>
        )}
      </div>
      {variant === "list" && total > 0 && (
        <div className="pager">
          <span>
            1–{total} of {total}
          </span>
          <button type="button" className="icon-btn" aria-label="Newer" disabled>
            <ChevronLeft size={18} />
          </button>
          <button type="button" className="icon-btn" aria-label="Older" disabled>
            <ChevronRight size={18} />
          </button>
        </div>
      )}
      {menu && (
        <PopMenu anchor={menu.anchor} onClose={() => setMenu(null)}>
          {menu.id === "snooze" && <SnoozeMenu ids={ids} onDone={() => setMenu(null)} />}
          {menu.id === "label" && <LabelMenu ids={ids} onDone={() => setMenu(null)} />}
          {menu.id === "move" && (
            <>
              <button type="button" className="menu-item" onClick={() => { mail.moveToInbox(ids); setMenu(null); }}>Inbox</button>
              <button type="button" className="menu-item" onClick={() => { mail.spam(ids); setMenu(null); }}>Spam</button>
              <button type="button" className="menu-item" onClick={() => { mail.trash(ids); setMenu(null); }}>Trash</button>
            </>
          )}
          {menu.id === "more" && (
            <>
              <button type="button" className="menu-item" onClick={() => { mail.mark(ids.length ? ids : mail.threads.map((thread) => thread.threadId), true); setMenu(null); }}>
                Mark as read
              </button>
              <button type="button" className="menu-item" onClick={() => { mail.mark(ids.length ? ids : undefined, false); setMenu(null); }}>
                Mark as unread
              </button>
              <button type="button" className="menu-item" onClick={() => { mail.star(ids); setMenu(null); }}>
                Star
              </button>
              <button
                type="button"
                className="menu-item"
                onClick={() => {
                  if (ids.length) mail.dispatch({ type: "important", threadIds: ids });
                  setMenu(null);
                }}
              >
                Toggle important
              </button>
              {variant === "list" && (
                <>
                  <button type="button" className="menu-item" onClick={() => { mail.selectMany(mail.threads.filter((thread) => thread.unread).map((thread) => thread.threadId)); setMenu(null); }}>
                    Select unread
                  </button>
                  <button type="button" className="menu-item" onClick={() => { mail.selectMany(mail.threads.filter((thread) => thread.starred).map((thread) => thread.threadId)); setMenu(null); }}>
                    Select starred
                  </button>
                  <button
                    type="button"
                    className="menu-item"
                    onClick={() => {
                      mail.dispatch({ type: "settings", patch: { previewPane: !mail.data.settings.previewPane } });
                      setMenu(null);
                    }}
                  >
                    {mail.data.settings.previewPane ? "Hide preview pane" : "Show preview pane"}
                  </button>
                </>
              )}
              {variant === "thread" && (
                <button
                  type="button"
                  className="menu-item"
                  onClick={() => {
                    window.print();
                    setMenu(null);
                  }}
                >
                  Print
                </button>
              )}
            </>
          )}
        </PopMenu>
      )}
    </div>
  );
}

function SnoozeMenu({ ids, onDone }: { ids: string[]; onDone: () => void }) {
  const { snooze } = useMail();
  const presets = snoozePresets();
  return (
    <>
      <p className="menu-label">Snooze until</p>
      {presets.map((preset) => (
        <button key={preset.id} type="button" className="menu-item" onClick={() => { snooze(ids, preset.until); onDone(); }}>
          <span>{preset.label}</span>
          <em>{preset.hint}</em>
        </button>
      ))}
      <label className="menu-item picker">
        <span>Pick date & time</span>
        <input
          type="datetime-local"
          onChange={(event) => {
            const until = new Date(event.target.value).getTime();
            if (!Number.isNaN(until)) {
              snooze(ids, until);
              onDone();
            }
          }}
        />
      </label>
    </>
  );
}

function LabelMenu({ ids, onDone }: { ids: string[]; onDone: () => void }) {
  const { data, setLabel, patchUi } = useMail();
  return (
    <>
      <p className="menu-label">Label as</p>
      {data.labels.map((label) => {
        const relevant = data.messages.filter((message) => ids.includes(message.threadId));
        const on = relevant.length > 0 && relevant.every((message) => message.labels.includes(label.id));
        return (
          <label key={label.id} className="menu-item check-item">
            <input
              type="checkbox"
              checked={on}
              onChange={() => setLabel(ids, label.id, !on)}
            />
            <i style={{ background: label.color }} />
            <span>{label.name}</span>
          </label>
        );
      })}
      <button type="button" className="menu-item" onClick={() => { patchUi({ createLabelOpen: true }); onDone(); }}>
        Create new
      </button>
    </>
  );
}

