}
.recipient > span { color: var(--faint); width: 28px; padding-top: 6px; }
.recipient-main { flex: 1; display: flex; flex-wrap: wrap; gap: 4px; position: relative; min-width: 0; }
.recipient input, .subject-input, .body-input {
  border: 0;
  outline: none;
  background: transparent;
  min-width: 80px;
  flex: 1;
}
.subject-input { width: 100%; }
.body-input { resize: none; flex: 1; min-height: 160px; padding: 12px; line-height: 1.5; }
.editor-wrap.inline .body-input { min-height: 120px; }
.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--chip);
  border-radius: 12px;
  padding: 2px 8px;
  font-size: 13px;
}
.chip button { border: 0; background: transparent; display: inline-flex; color: var(--muted); }
.suggest, .schedule-pop {
  position: absolute;
  z-index: 5;
  left: 0;
  top: calc(100% + 4px);
  background: var(--menu);
  box-shadow: var(--shadow);
  border-radius: 12px;
  min-width: 240px;
  padding: 6px 0;
}
.suggest button {
  width: 100%;
  border: 0;
  background: transparent;
  text-align: left;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
}
.suggest button.on, .suggest button:hover { background: var(--hover); }
.suggest em { color: var(--faint); font-style: normal; font-size: 12px; }
.cc-toggles { margin-left: auto; display: flex; gap: 8px; padding-top: 4px; }
.compose-foot {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px;
  position: relative;
}
.send-split { position: relative; display: flex; }
.send-btn, .send-more {
  border: 0;
  background: var(--accent);
  color: white;
  height: 36px;
}
html[data-theme="dark"] .send-btn, html[data-theme="dark"] .send-more { color: #062e6f; }
.send-btn { border-radius: 18px 0 0 18px; padding: 0 16px; font-weight: 500; }
.send-more { border-radius: 0 18px 18px 0; width: 32px; border-left: 1px solid rgba(255, 255, 255, 0.25); display: inline-flex; align-items: center; justify-content: center; }
.format-bar { display: flex; }
.draft-state, .sig-note { color: var(--faint); font-size: 12px; margin-left: 8px; }
.compose-foot .icon-btn { margin-left: auto; }
.compose-atts { margin: 0 12px 8px; }
.warn, .form-error { margin: 8px 12px 0; color: var(--danger); display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.menu {
  position: fixed;
  z-index: 40;
  background: var(--menu);
  border-radius: 8px;
  box-shadow: var(--shadow);
  padding: 6px 0;
  max-height: min(360px, calc(100dvh - 24px));
  overflow: auto;
}
.menu-item em { margin-left: auto; color: var(--faint); font-style: normal; font-size: 12px; }
.check-item { align-items: center; }
.check-item i, .label-row i { width: 12px; height: 12px; border-radius: 50%; display: inline-block; }
.picker { flex-wrap: wrap; }
.picker input { width: 100%; margin-top: 6px; }
.modal-back {
  position: fixed;
  inset: 0;
  background: rgba(32, 33, 36, 0.45);
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 16px;
}
.modal {
  width: min(440px, 100%);
  background: var(--bg);
  color: var(--text);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 8px 8px 16px;
}
.modal.wide { width: min(640px, 100%); }
.modal-head { display: flex; align-items: center; padding: 8px 8px 8px 16px; }
.modal-head h2 { margin: 0; font-size: 18px; font-weight: 500; flex: 1; }
.modal-copy { padding: 0 16px; color: var(--muted); }
.modal-actions { display: flex; justify-content: flex-end; gap: 8px; padding: 12px 16px 0; }
.btn {
  border-radius: 18px;
  border: 0;
  height: 36px;
  padding: 0 16px;
  font-weight: 500;
}
.btn.primary { background: var(--accent); color: white; }
html[data-theme="dark"] .btn.primary { color: #062e6f; }
.btn.ghost { background: transparent; color: var(--accent); }
.btn.danger { background: transparent; }
.stack, .settings { display: flex; flex-direction: column; gap: 8px; padding: 0 16px; }
.stack input, .stack textarea, .label-row input, .settings input[type="text"], .modal input, .modal textarea {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
  padding: 8px 10px;
  width: 100%;
}
fieldset { border: 0; padding: 0; margin: 0; }
legend { font-size: 12px; color: var(--faint); margin-bottom: 6px; }
.segmented { display: flex; background: var(--search); border-radius: 10px; padding: 3px; }
.segmented button { flex: 1; border: 0; background: transparent; border-radius: 8px; height: 32px; text-transform: capitalize; }
.segmented button.on { background: var(--bg); box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12); font-weight: 500; }
.check-row { display: flex; gap: 8px; align-items: center; }
.swatches { display: flex; gap: 8px; padding: 8px 16px 0; }
.swatch { width: 24px; height: 24px; border-radius: 50%; border: 2px solid transparent; }
.swatch.on { border-color: var(--text); }
.label-editor { display: flex; flex-direction: column; gap: 8px; }
.label-row { display: flex; align-items: center; gap: 8px; }
.shortcuts { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 24px; padding: 8px 16px 16px; }
.shortcuts div { display: flex; justify-content: space-between; gap: 12px; border-bottom: 1px solid var(--line); padding-bottom: 6px; }
kbd { font-family: var(--font); background: var(--chip); border-radius: 6px; padding: 2px 6px; }
.preview { white-space: pre-wrap; background: var(--canvas); border-radius: 12px; padding: 12px; margin: 0 16px; max-height: 360px; overflow: auto; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 12px; }
.snack {
  position: fixed;
  left: 24px;
  bottom: 24px;
  z-index: 45;
  background: #323232;
  color: white;
  border-radius: 8px;
  min-height: 48px;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 8px 0 16px;
  box-shadow: var(--shadow);
}
.snack button { border: 0; background: transparent; color: #a8c7fa; font-weight: 500; height: 40px; padding: 0 12px; }
.fab {
  position: fixed;
  right: 16px;
  bottom: 16px;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  border: 0;
  background: var(--compose);
  color: #001d35;
  display: none;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow);
  z-index: 15;
}
.backdrop { position: fixed; inset: 0; border: 0; background: rgba(32, 33, 36, 0.4); z-index: 20; }
.signed-out {
  min-height: 100dvh;
  display: grid;
  place-items: center;
  background:
    radial-gradient(900px 400px at 10% -10%, #d3e3fd, transparent 50%),
    var(--canvas);
}
.signed-out section {
  width: min(420px, calc(100% - 32px));
  background: var(--bg);
  border-radius: 24px;
  padding: 32px;
  box-shadow: var(--shadow);
}
.signed-out h1 { margin: 0 0 8px; font-size: 32px; font-weight: 500; color: var(--muted); }
.signed-out p { color: var(--muted); line-height: 1.5; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

@media (hover: none) {
  .row-actions { display: none !important; }
  .row:hover .when { visibility: visible; }
}

@media (max-width: 759px) {
  .app { grid-template-columns: 1fr; }
  .brand { width: auto; min-width: 0; }
  .brand h1 { font-size: 20px; }
  .nav {
    position: fixed;
    z-index: 25;
    top: 64px;
    bottom: 0;
    left: 0;
    width: min(300px, 88vw);
    background: var(--canvas);
    transform: translateX(-105%);
    transition: transform 0.18s ease;
    box-shadow: var(--shadow);
  }
  .nav.open { transform: none; }
  .main-card { margin: 0 0 0 0; border-radius: 0; }
  .search { max-width: none; }
  .top-actions .icon-btn:first-child { display: none; }
  .row {
    grid-template-columns: 24px 24px minmax(0, 1fr) auto;
    grid-template-areas: "check star people when" "check star subject subject";
    height: auto;
    min-height: 64px;
    padding: 8px 8px 8px 0;
    align-items: start;
  }
  .row .check { grid-area: check; }
  .row .star { grid-area: star; }
  .people { grid-area: people; font-size: 14px; padding-top: 6px; }
  .subject-line { grid-area: subject; padding-bottom: 4px; }
  .when { grid-area: when; padding-top: 8px; }
  .pill, .thread-count, .clip { display: none; }
  .msg-body, .signature, .quote-wrap, .attachments { padding-left: 0; margin-left: 0; }
  .reply-launch { margin-left: 16px; }
  .editor-wrap.inline { margin-left: 12px; margin-right: 12px; }
  .fab { display: inline-flex; }
  .shortcuts { grid-template-columns: 1fr; }
  .compose.full { inset: 0; border-radius: 0; }
}

@media print {
  .topbar, .nav, .toolbar, .compose, .snack, .fab, .reply-launch, .banner button { display: none !important; }
  .app { display: block; height: auto; background: white; }
  .main-card { display: block; margin: 0; box-shadow: none; }
  .thread { overflow: visible; }
}

