              className={`row ${thread.unread ? "unread" : ""} ${selected ? "selected" : ""} ${active ? "active" : ""} ${index === ui.cursor ? "cursor" : ""}`}
              onClick={() => {
                mail.patchUi({ cursor: index });
                openThread(thread.threadId);
              }}
            >
