.fab {
  position: fixed;
  right: 16px;
  bottom: 16px;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  border: 0;
  background: var(--compose);
  color: #001d35;
  display: none;
  align-items: center;
  justify-content: center;
