}
.nav-item.active { background: var(--nav-active); font-weight: 700; }
.nav-item:hover { background: var(--hover); }
.nav-item.active:hover { background: var(--nav-active); }
.nav-item .count { margin-left: auto; font-style: normal; font-weight: 700; font-size: 13px; }
.nav-section {
  display: flex;
