.app[data-collapsed="true"] .nav-item .count,
.app[data-collapsed="true"] .compose-btn span,
.app[data-collapsed="true"] .nav-section,
.app[data-collapsed="true"] .text-btn { display: none; }
.app[data-collapsed="true"] .nav-item,
.app[data-collapsed="true"] .compose-btn {
