}
.subject { flex: 0 1 auto; max-width: 46%; }
.snippet { flex: 1 1 auto; }
.sep { color: var(--faint); flex: none; }
.people { display: flex; align-items: center; gap: 6px; }
.important {
  width: 0;
  height: 0;
