}
.subject-line { display: flex; align-items: center; gap: 6px; min-width: 0; }
.snippet, .when, .thread-count { color: var(--faint); font-weight: 400; }
.thread-count { font-size: 12px; }
.draft-tag { color: #b3261e; font-weight: 700; flex: none; }
html[data-theme="dark"] .draft-tag { color: #f2b8b5; }
.pill {
