}

.thread { overflow: auto; flex: 1; padding-bottom: 24px; }
.subject-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px 4px;
  flex-wrap: wrap;
}
.subject-head h2 { margin: 0; font-size: 22px; font-weight: 400; }
.head-labels { display: flex; gap: 6px; flex-wrap: wrap; }
.banner {
  margin: 8px 16px;
  background: var(--search);
  border-radius: 12px;
